<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Maikot Business Manager</title><link rel="stylesheet" href="assets/css/style.css"></head><body><aside class="sidebar"><div class="brand">Maikot Computer & Stationery</div><div class="subbrand">Purchase & Supplier Manager v1</div><div class="nav"><button class="active" onclick="showPanel('dashboard',this)">Dashboard</button><button onclick="showPanel('products',this)">Products</button><button onclick="showPanel('suppliers',this)">Suppliers</button><button onclick="showPanel('purchases',this)">Purchase Entry</button><button onclick="showPanel('comparison',this)">Price Comparison</button></div></aside><main class="main"><h1 id="pageTitle">Dashboard</h1><section id="dashboard" class="panel active"><div class="cards"><div class="card"><div class="label">Products</div><div class="value" id="productsCount">0</div></div><div class="card"><div class="label">Suppliers</div><div class="value" id="suppliersCount">0</div></div><div class="card"><div class="label">Purchase Entries</div><div class="value" id="purchasesCount">0</div></div><div class="card"><div class="label">Total Purchase</div><div class="value" id="totalPurchase">Rs. 0</div></div></div><div class="box"><h3>Version 1</h3><p>Add products, suppliers and purchases, then compare the same product across wholesalers.</p></div></section><section id="products" class="panel"><div class="box"><h3>Add Product</h3><form id="productForm"><div class="grid"><label>Product Code<input name="product_code" required></label><label>Product Name<input name="product_name" required></label><label>Category<input name="category"></label><label>Brand / Model<input name="brand_model"></label><label>Unit<input name="unit" value="Piece"></label><label>Selling Price<input name="selling_price" type="number" step="0.01" value="0"></label></div><div class="actions"><button class="primary">Save Product</button></div></form></div><div class="box"><table><thead><tr><th>Code</th><th>Product</th><th>Category</th><th>Brand/Model</th><th>Unit</th><th>Selling Price</th></tr></thead><tbody id="productBody"></tbody></table></div></section><section id="suppliers" class="panel"><div class="box"><h3>Add Supplier</h3><form id="supplierForm"><div class="grid"><label>Supplier Code<input name="supplier_code" required></label><label>Supplier Name<input name="supplier_name" required></label><label>Contact Person<input name="contact_person"></label><label>Phone<input name="phone"></label><label>Address<input name="address"></label><label>PAN/VAT No.<input name="pan_vat"></label></div><div class="actions"><button class="primary">Save Supplier</button></div></form></div><div class="box"><table><thead><tr><th>Code</th><th>Supplier</th><th>Contact Person</th><th>Phone</th><th>Address</th></tr></thead><tbody id="supplierBody"></tbody></table></div></section><section id="purchases" class="panel"><div class="box"><h3>New Purchase Entry</h3><form id="purchaseForm"><div class="grid"><label>Date<input id="purchaseDate" name="purchase_date" type="date" required></label><label>Product<select id="purchaseProduct" name="product_id" required></select></label><label>Supplier<select id="purchaseSupplier" name="supplier_id" required></select></label><label>Quantity<input name="qty" type="number" step="0.01" required></label><label>Purchase Rate / Unit<input name="purchase_rate" type="number" step="0.01" required></label><label>Discount<input name="discount" type="number" step="0.01" value="0"></label><label>Transport<input name="transport" type="number" step="0.01" value="0"></label><label>Other Cost<input name="other_cost" type="number" step="0.01" value="0"></label></div><div class="actions"><button class="primary">Save Purchase</button></div></form></div><div class="box"><table><thead><tr><th>Date</th><th>Product</th><th>Supplier</th><th>Qty</th><th>Rate</th><th>Actual Cost/Unit</th><th>Selling Price</th><th>Profit/Unit</th></tr></thead><tbody id="purchaseBody"></tbody></table></div></section><section id="comparison" class="panel"><div class="box"><h3>Compare Supplier Prices</h3><label>Select Product<select id="compareProduct"></select></label></div><div class="box"><table><thead><tr><th>Date</th><th>Supplier</th><th>Qty</th><th>Rate</th><th>Discount</th><th>Extra Cost</th><th>Actual Cost/Unit</th></tr></thead><tbody id="comparisonBody"></tbody></table><p class="muted">⭐ = lowest recorded actual unit cost.</p></div></section></main><script src="assets/js/app.js"></script></body></html>